import {reportMoney,type ReportCell} from '@/lib/report-export';

export const depositLimit=999999999999;
export const depositKinds={external_receipt:'External security funds received',external_refund:'External security funds returned',receipt_reduction:'Receipt record reduction'} as const;
export const depositMethods={cash:'Cash',card:'Card',bank_transfer:'Bank transfer',other:'Other'} as const;
export type DepositKind=keyof typeof depositKinds;
export type DepositMethod=keyof typeof depositMethods;
export type DepositTotals={received_minor:number;refunded_minor:number;reduced_minor:number;held_minor:number};
export type DepositReservation={id:string;source:'direct'|'migration'|'iratepilot-ota';source_booking_id:string;status:'Confirmed'|'In house'|'Checked out'|'Cancelled';cancellation_kind:null|'no_show';guest_name:string|null;arrival:string|null;departure:string|null};
export type DepositBook={id:string;reservation_id:string;version:number;currency:'USD';recording_time_zone:string;creation_operating_model:'hotel'|'whole_home';created_at:string;created_by:string;updated_at:string;totals:DepositTotals};
export type DepositEvent={id:string;book_id:string;reservation_id:string;request_id:string;kind:DepositKind;amount_minor:number;currency:'USD';target_event_id:string|null;recorded_method:DepositMethod|null;reference:string;reason:string;actor_id:string;recorded_at:string;recording_time_zone:string;recording_date:string;from_version:number;to_version:number};
export type DepositTarget={event_id:string;received_minor:number;refunded_minor:number;reduced_minor:number;remaining_minor:number};
type DepositCommon={schema_version:1;tenant_id:string;property_id:string;recording_mode:'external_only';purpose:'refundable_security'};
export type DepositDetail=DepositCommon&{reservation:DepositReservation;role:string;can_manage:boolean;property_time_zone:string;recording_time_zone:string;recording_date:string;generated_at:string;book:DepositBook|null;version:number;totals:DepositTotals|null;events:DepositEvent[];refundable_receipts:DepositTarget[];folio_changed:false;rows_truncated:false};
export type DepositCommand={reservation_id:string;expected_version:number;expected_recording_time_zone:string;expected_recording_date:string;kind:DepositKind;amount_minor:number;method:DepositMethod|null;reference:string;reason:string;target_event_id:string|null;confirmed:true};
export type DepositRecorded=DepositCommon&{outcome:'recorded';request_id:string;action:'record_security_deposit';book:DepositBook;event:DepositEvent;expected_version:number;recording_date:string;recording_time_zone:string;folio_changed:false;revenue_changed:false;replayed:boolean};
export type DepositRetired={schema_version:1;outcome:'retired';tenant_id:string;property_id:string;reservation_id:string;request_id:string;action:'retire_security_deposit_request';command:DepositCommand;retirement_reason:string;retired_by:string;retired_at:string;book_version_changed:false;financial_changed:false;folio_changed:false;revenue_changed:false;replayed:boolean};
export type DepositOutcome=DepositRecorded|DepositRetired;
export type DepositStatus={found:false}|{found:true;action:'record_security_deposit'|'retire_security_deposit_request';result:DepositOutcome};
export type DepositRegister=DepositCommon&{generated_at:string;property_time_zone:string;role:string;can_manage:boolean;currency:'USD';rows:{reservation:DepositReservation;book:DepositBook;financial_review_required:boolean}[];totals:DepositTotals;summary:{book_count:number;with_held_count:number;zero_held_count:number;ended_with_held_count:number;ended_held_minor:number};rows_truncated:false;definitions:Record<string,string>};
export type DepositActivity=DepositCommon&{generated_at:string;property_time_zone:string;currency:'USD';period:{start:string;end:string;end_exclusive:true;basis:'stored_recording_date'};rows:{reservation:DepositReservation;event:DepositEvent;held_effect_minor:number}[];totals:{event_count:number;received_minor:number;refunded_minor:number;reduced_minor:number;held_effect_minor:number};rows_truncated:false;definitions:Record<string,string>};
export type DepositPending={schema_version:1;actor:string;tenant:string;property:string;reservation:string;request:string;command:DepositCommand;review:{book:DepositBook|null;target_remaining_minor:number|null};retirement_reason:string|null};
export type DepositScope={actor:string;tenant:string;property:string;reservation:string};

const record=(v:unknown):v is Record<string,unknown>=>!!v&&typeof v==='object'&&!Array.isArray(v);
const uuid=(v:unknown):v is string=>typeof v==='string'&&/^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(v);
const integer=(v:unknown,min=0,max=Number.MAX_SAFE_INTEGER):v is number=>typeof v==='number'&&Number.isSafeInteger(v)&&v>=min&&v<=max;
const timestamp=(v:unknown):v is string=>typeof v==='string'&&/T| /.test(v)&&Number.isFinite(Date.parse(v));
const exact=(v:Record<string,unknown>,keys:string[])=>Object.keys(v).sort().join('|')===[...keys].sort().join('|');
function ordered(value:unknown):unknown{if(Array.isArray(value))return value.map(ordered);if(record(value))return Object.fromEntries(Object.keys(value).sort().map(key=>[key,ordered(value[key])]));return value}
const same=(a:unknown,b:unknown)=>JSON.stringify(ordered(a))===JSON.stringify(ordered(b));
function fail(message='The security-deposit response is incomplete or inconsistent. Refresh before continuing.'):never{throw Error(message)}
const sum=(a:number,b:number,max=Number.MAX_SAFE_INTEGER)=>{const value=a+b;if(!Number.isSafeInteger(value)||Math.abs(value)>max)fail('Security-deposit amounts exceed the exact supported limit.');return value};
const zero=():DepositTotals=>({received_minor:0,refunded_minor:0,reduced_minor:0,held_minor:0});
export function depositDate(v:unknown):v is string{return typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&v.slice(0,4)!=='0000'&&Number.isFinite(Date.parse(v+'T00:00:00Z'))&&new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v}
export function depositZoneDate(at:string,zone:string){try{const parts=new Intl.DateTimeFormat('en-US',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(at));const get=(type:string)=>parts.find(p=>p.type===type)?.value??'';return get('year').padStart(4,'0')+'-'+get('month')+'-'+get('day')}catch{return ''}}
const zone=(v:unknown):v is string=>typeof v==='string'&&v.trim()===v&&v.length>0&&v.length<=100&&!!depositZoneDate('2027-01-02T12:00:00Z',v);
const text=(v:unknown,min:number,max:number):v is string=>typeof v==='string'&&v.trim()===v&&Array.from(v).length>=min&&Array.from(v).length<=max&&!Array.from(v).some(c=>c.charCodeAt(0)<32||c.charCodeAt(0)===127);
const nullableDate=(v:unknown)=>v===null||depositDate(v);
const totals=(v:unknown,max=depositLimit):v is DepositTotals=>record(v)&&exact(v,['received_minor','refunded_minor','reduced_minor','held_minor'])&&['received_minor','refunded_minor','reduced_minor','held_minor'].every(k=>integer(v[k],0,max))&&v.held_minor===(v.received_minor as number)-(v.refunded_minor as number)-(v.reduced_minor as number);
const role=(v:unknown,manage:unknown)=>['owner','manager','staff'].includes(String(v))&&manage===['owner','manager'].includes(String(v));
const definitions=(v:unknown)=>record(v)&&Object.values(v).every(item=>typeof item==='string');
function reservation(v:unknown):v is DepositReservation{return record(v)&&uuid(v.id)&&['direct','migration','iratepilot-ota'].includes(String(v.source))&&typeof v.source_booking_id==='string'&&['Confirmed','In house','Checked out','Cancelled'].includes(String(v.status))&&(v.cancellation_kind===null||v.cancellation_kind==='no_show'&&v.status==='Cancelled')&&(v.guest_name===null||typeof v.guest_name==='string')&&nullableDate(v.arrival)&&nullableDate(v.departure)}
function book(v:unknown):v is DepositBook{return record(v)&&exact(v,['id','reservation_id','version','currency','recording_time_zone','creation_operating_model','created_at','created_by','updated_at','totals'])&&uuid(v.id)&&uuid(v.reservation_id)&&integer(v.version,1,1000)&&v.currency==='USD'&&zone(v.recording_time_zone)&&['hotel','whole_home'].includes(String(v.creation_operating_model))&&timestamp(v.created_at)&&timestamp(v.updated_at)&&uuid(v.created_by)&&totals(v.totals)&&v.totals.received_minor>0}
function event(v:unknown):v is DepositEvent{return record(v)&&[v.id,v.book_id,v.reservation_id,v.request_id,v.actor_id].every(uuid)&&Object.hasOwn(depositKinds,String(v.kind))&&integer(v.amount_minor,1,depositLimit)&&v.currency==='USD'&&text(v.reference,4,200)&&text(v.reason,4,500)&&timestamp(v.recorded_at)&&zone(v.recording_time_zone)&&depositDate(v.recording_date)&&depositZoneDate(v.recorded_at,v.recording_time_zone)===v.recording_date&&integer(v.from_version,0,999)&&v.to_version===v.from_version+1&&(v.kind==='external_receipt'?v.target_event_id===null:uuid(v.target_event_id))&&(v.kind==='receipt_reduction'?v.recorded_method===null:Object.hasOwn(depositMethods,String(v.recorded_method)))}
function common(v:unknown,tenant:string,property:string):v is Record<string,unknown>{return record(v)&&v.schema_version===1&&v.tenant_id===tenant&&v.property_id===property&&v.recording_mode==='external_only'&&v.purpose==='refundable_security'}
function apply(total:DepositTotals,kind:DepositKind,amount:number,max=depositLimit){const next={...total};const key=kind==='external_receipt'?'received_minor':kind==='external_refund'?'refunded_minor':'reduced_minor';next[key]=sum(next[key],amount,max);next.held_minor=next.received_minor-next.refunded_minor-next.reduced_minor;if(!totals(next,max))fail();return next}
const equalTotals=(a:DepositTotals,b:DepositTotals)=>['received_minor','refunded_minor','reduced_minor','held_minor'].every(k=>a[k as keyof DepositTotals]===b[k as keyof DepositTotals]);
export function depositPeriod(start:string,end:string){if(!depositDate(start)||!depositDate(end))return false;const nights=(Date.parse(end+'T00:00:00Z')-Date.parse(start+'T00:00:00Z'))/86400000;return nights>=1&&nights<=366}
export function addDepositDays(date:string,days:number){return new Date(Date.parse(date+'T00:00:00Z')+days*86400000).toISOString().slice(0,10)}
export function depositAmount(value:string){if(!/^(?:0|[1-9]\d*)(?:\.\d{1,2})?$/.test(value.trim()))fail('Enter a positive USD amount with at most two decimal places.');const [whole,part='']=value.trim().split('.');const amount=Number(whole)*100+Number(part.padEnd(2,'0'));if(!integer(amount,1,depositLimit))fail('Enter an amount between $0.01 and $9,999,999,999.99.');return amount}
export function depositText(value:string,min:number,max:number){const normalized=value.trim();if(!text(normalized,min,max))fail(`Enter ${min}–${max} characters without control characters.`);return normalized}
export function depositStatusLabel(value:DepositReservation){return value.cancellation_kind==='no_show'?'No show':value.status}

export function validateDepositDetail(value:unknown,tenant:string,property:string,reservationId:string):asserts value is DepositDetail{
 if(!common(value,tenant,property)||!reservation(value.reservation)||value.reservation.id!==reservationId||!role(value.role,value.can_manage)||!zone(value.property_time_zone)||!zone(value.recording_time_zone)||!timestamp(value.generated_at)||!depositDate(value.recording_date)||depositZoneDate(value.generated_at,value.recording_time_zone)!==value.recording_date||value.folio_changed!==false||value.rows_truncated!==false||!Array.isArray(value.events)||!Array.isArray(value.refundable_receipts)||value.events.length>1000)fail();
 const d=value as unknown as DepositDetail;
 if(d.book===null){if(d.version!==0||d.totals!==null||d.events.length||d.refundable_receipts.length||d.recording_time_zone!==d.property_time_zone)fail();return}
 if(!book(d.book)||d.book.reservation_id!==reservationId||d.version!==d.book.version||d.events.length!==d.version||d.book.recording_time_zone!==d.recording_time_zone||!totals(d.totals)||!equalTotals(d.totals,d.book.totals))fail();
 let running=zero();const ids=new Set<string>(),requests=new Set<string>(),targets=new Map<string,DepositTarget>();
 for(const [index,e] of d.events.entries()){
  if(!event(e)||ids.has(e.id)||requests.has(e.request_id)||e.book_id!==d.book.id||e.reservation_id!==reservationId||e.recording_time_zone!==d.book.recording_time_zone||e.from_version!==index||e.to_version!==index+1)fail();
  ids.add(e.id);requests.add(e.request_id);
  if(e.kind==='external_receipt')targets.set(e.id,{event_id:e.id,received_minor:e.amount_minor,refunded_minor:0,reduced_minor:0,remaining_minor:e.amount_minor});
  else{const target=targets.get(e.target_event_id!);if(!target||target.remaining_minor<e.amount_minor)fail();target[e.kind==='external_refund'?'refunded_minor':'reduced_minor']=sum(target[e.kind==='external_refund'?'refunded_minor':'reduced_minor'],e.amount_minor,depositLimit);target.remaining_minor-=e.amount_minor}
  running=apply(running,e.kind,e.amount_minor);
 }
 const first=d.events[0],last=d.events.at(-1)!;
 if(first.kind!=='external_receipt'||first.actor_id!==d.book.created_by||first.recorded_at!==d.book.created_at||last.recorded_at!==d.book.updated_at||!equalTotals(running,d.book.totals)||!same([...targets.values()],d.refundable_receipts))fail();
}

const commandKeys=['reservation_id','expected_version','expected_recording_time_zone','expected_recording_date','kind','amount_minor','method','reference','reason','target_event_id','confirmed'];
function validCommand(value:unknown):value is DepositCommand{return record(value)&&exact(value,commandKeys)&&uuid(value.reservation_id)&&integer(value.expected_version,0,1000)&&zone(value.expected_recording_time_zone)&&depositDate(value.expected_recording_date)&&typeof value.kind==='string'&&Object.hasOwn(depositKinds,value.kind)&&integer(value.amount_minor,1,depositLimit)&&text(value.reference,4,200)&&text(value.reason,4,500)&&value.confirmed===true&&(value.kind==='external_receipt'?value.target_event_id===null:uuid(value.target_event_id))&&(value.kind==='receipt_reduction'?value.method===null:typeof value.method==='string'&&Object.hasOwn(depositMethods,value.method))}
export function depositKey(scope:DepositScope){return 'iratepilot-pms-pending-deposit:'+scope.actor+':'+scope.tenant+':'+scope.property+':'+scope.reservation}
export function validateDepositPending(value:unknown,scope:DepositScope):asserts value is DepositPending{
 if(!record(value)||!exact(value,['schema_version','actor','tenant','property','reservation','request','command','review','retirement_reason'])||value.schema_version!==1||!Object.values(scope).every(uuid)||value.actor!==scope.actor||value.tenant!==scope.tenant||value.property!==scope.property||value.reservation!==scope.reservation||!uuid(value.request)||!validCommand(value.command)||value.command.reservation_id!==scope.reservation||!record(value.review)||!exact(value.review,['book','target_remaining_minor'])||!(value.retirement_reason===null||text(value.retirement_reason,4,500)))fail('The saved security-deposit request is incomplete or belongs to another scope. Keep it for reconciliation.');
 const p=value as unknown as DepositPending,b=p.review.book;
 if(b===null?p.command.expected_version!==0||p.command.kind!=='external_receipt':!book(b)||b.reservation_id!==p.reservation||b.version!==p.command.expected_version||b.recording_time_zone!==p.command.expected_recording_time_zone)fail('The saved security-deposit review does not match its command. Keep it for reconciliation.');
 if(p.command.kind==='external_receipt'?p.review.target_remaining_minor!==null:!integer(p.review.target_remaining_minor,1,depositLimit)||p.command.amount_minor>p.review.target_remaining_minor)fail('The saved security-deposit target review is incomplete.');
 apply(b?.totals??zero(),p.command.kind,p.command.amount_minor);
}
export function depositPostArgs(p:DepositPending){const c=p.command;return {p_tenant:p.tenant,p_property:p.property,p_reservation:p.reservation,p_request:p.request,p_expected_version:c.expected_version,p_expected_recording_time_zone:c.expected_recording_time_zone,p_expected_recording_date:c.expected_recording_date,p_kind:c.kind,p_amount_minor:c.amount_minor,p_method:c.method,p_reference:c.reference,p_reason:c.reason,p_target:c.target_event_id,p_confirmed:true}}
export function depositRetireArgs(p:DepositPending){if(!p.retirement_reason)fail('Review why this request should stop retrying.');return {p_tenant:p.tenant,p_property:p.property,p_reservation:p.reservation,p_request:p.request,p_command:p.command,p_reason:p.retirement_reason}}
export function validateDepositOutcome(value:unknown,p:DepositPending):asserts value is DepositOutcome{
 const bad:()=>never=()=>fail('The saved security-deposit outcome does not match this exact request. Keep the request and check again.');
 if(!record(value)||value.schema_version!==1||value.tenant_id!==p.tenant||value.property_id!==p.property||value.request_id!==p.request||typeof value.replayed!=='boolean'||value.folio_changed!==false||value.revenue_changed!==false)bad();
 if(value.outcome==='retired'){
  if(!exact(value,['schema_version','outcome','tenant_id','property_id','reservation_id','request_id','action','command','retirement_reason','retired_by','retired_at','book_version_changed','financial_changed','folio_changed','revenue_changed','replayed'])||value.action!=='retire_security_deposit_request'||value.reservation_id!==p.reservation||value.retired_by!==p.actor||!timestamp(value.retired_at)||value.book_version_changed!==false||value.financial_changed!==false||!validCommand(value.command)||!same(value.command,p.command)||!text(value.retirement_reason,4,500)||p.retirement_reason!==null&&value.retirement_reason!==p.retirement_reason)bad();
  return;
 }
 if(!common(value,p.tenant,p.property)||value.outcome!=='recorded'||value.action!=='record_security_deposit'||!book(value.book)||!event(value.event))bad();
 const r=value as unknown as DepositRecorded,c=p.command,e=r.event,b=r.book,prior=p.review.book;
 if(r.expected_version!==c.expected_version||r.recording_date!==c.expected_recording_date||r.recording_time_zone!==c.expected_recording_time_zone||b.reservation_id!==p.reservation||b.version!==c.expected_version+1||b.recording_time_zone!==c.expected_recording_time_zone||b.updated_at!==e.recorded_at||e.book_id!==b.id||e.reservation_id!==p.reservation||e.request_id!==p.request||e.actor_id!==p.actor||e.from_version!==c.expected_version||e.to_version!==b.version||e.recording_date!==r.recording_date||e.recording_time_zone!==r.recording_time_zone||e.kind!==c.kind||e.amount_minor!==c.amount_minor||e.recorded_method!==c.method||e.target_event_id!==c.target_event_id||e.reference!==c.reference||e.reason!==c.reason||!equalTotals(b.totals,apply(prior?.totals??zero(),c.kind,c.amount_minor)))bad();
 if(prior?b.id!==prior.id||b.created_at!==prior.created_at||b.created_by!==prior.created_by||b.creation_operating_model!==prior.creation_operating_model:b.created_at!==e.recorded_at||b.created_by!==p.actor)bad();
}
export function validateDepositStatus(value:unknown,p:DepositPending):asserts value is DepositStatus{if(!record(value)||typeof value.found!=='boolean')fail('The security-deposit request lookup is incomplete.');if(!value.found){if(!exact(value,['found']))fail();return}if(!exact(value,['found','action','result']))fail();validateDepositOutcome(value.result,p);if(value.action!==value.result.action||value.result.replayed!==false)fail('The security-deposit status must contain its original immutable outcome, not a mutation replay.')}

export function validateDepositRegister(value:unknown,tenant:string,property:string):asserts value is DepositRegister{
 if(!common(value,tenant,property)||!timestamp(value.generated_at)||!zone(value.property_time_zone)||!role(value.role,value.can_manage)||value.currency!=='USD'||value.rows_truncated!==false||!definitions(value.definitions)||!Array.isArray(value.rows)||value.rows.length>10000||!totals(value.totals,Number.MAX_SAFE_INTEGER)||!record(value.summary))fail();
 const r=value as unknown as DepositRegister,ids=new Set<string>(),reservations=new Set<string>();const total=zero();let withHeld=0,ended=0,endedHeld=0;
 for(const row of r.rows){if(!record(row)||!reservation(row.reservation)||!book(row.book)||row.book.reservation_id!==row.reservation.id||ids.has(row.book.id)||reservations.has(row.reservation.id))fail();ids.add(row.book.id);reservations.add(row.reservation.id);const review=row.book.totals.held_minor>0&&['Checked out','Cancelled'].includes(row.reservation.status);if(row.financial_review_required!==review)fail();if(row.book.totals.held_minor>0)withHeld++;if(review){ended++;endedHeld=sum(endedHeld,row.book.totals.held_minor)};for(const key of ['received_minor','refunded_minor','reduced_minor','held_minor'] as const)total[key]=sum(total[key],row.book.totals[key])}
 if(!equalTotals(total,r.totals)||!same(r.summary,{book_count:r.rows.length,with_held_count:withHeld,zero_held_count:r.rows.length-withHeld,ended_with_held_count:ended,ended_held_minor:endedHeld}))fail();
}
export function validateDepositActivity(value:unknown,tenant:string,property:string,start:string,end:string):asserts value is DepositActivity{
 if(!depositPeriod(start,end)||!common(value,tenant,property)||!timestamp(value.generated_at)||!zone(value.property_time_zone)||value.currency!=='USD'||value.rows_truncated!==false||!definitions(value.definitions)||!Array.isArray(value.rows)||value.rows.length>10000||!same(value.period,{start,end,end_exclusive:true,basis:'stored_recording_date'})||!record(value.totals))fail();
 const r=value as unknown as DepositActivity,ids=new Set<string>(),requests=new Set<string>(),versions=new Set<string>(),labels=new Map<string,DepositReservation>(),bookScopes=new Map<string,string>(),reservationBooks=new Map<string,string>();let received=0,refunded=0,reduced=0,effect=0;
 for(const row of r.rows){if(!record(row)||!reservation(row.reservation)||!event(row.event)||row.event.reservation_id!==row.reservation.id||row.event.recording_date<start||row.event.recording_date>=end||ids.has(row.event.id)||requests.has(row.event.request_id)||versions.has(row.event.book_id+'/'+row.event.to_version))fail();const e=row.event,oldLabel=labels.get(row.reservation.id),bookScope=e.reservation_id+'/'+e.recording_time_zone;if(oldLabel&&!same(oldLabel,row.reservation)||bookScopes.has(e.book_id)&&bookScopes.get(e.book_id)!==bookScope||reservationBooks.has(e.reservation_id)&&reservationBooks.get(e.reservation_id)!==e.book_id)fail();labels.set(row.reservation.id,row.reservation);bookScopes.set(e.book_id,bookScope);reservationBooks.set(e.reservation_id,e.book_id);const delta=e.kind==='external_receipt'?e.amount_minor:-e.amount_minor;if(row.held_effect_minor!==delta)fail();ids.add(e.id);requests.add(e.request_id);versions.add(e.book_id+'/'+e.to_version);effect=sum(effect,delta);if(e.kind==='external_receipt')received=sum(received,e.amount_minor);else if(e.kind==='external_refund')refunded=sum(refunded,e.amount_minor);else reduced=sum(reduced,e.amount_minor)}
 if(!same(r.totals,{event_count:r.rows.length,received_minor:received,refunded_minor:refunded,reduced_minor:reduced,held_effect_minor:effect})||effect!==received-refunded-reduced)fail();
}

export const depositEventHeaders=['Recorded at','Recording date','Frozen recording time zone','Event','Book','Reservation','Request','Version before','Version after','Kind','Amount USD','Held effect USD','Recorded method','Document reference','Reason','Original receipt target','Actor'];
export function depositEventRows(events:DepositEvent[]):ReportCell[][]{return events.map(e=>[e.recorded_at,e.recording_date,e.recording_time_zone,e.id,e.book_id,e.reservation_id,e.request_id,e.from_version,e.to_version,depositKinds[e.kind],reportMoney(e.amount_minor),reportMoney(e.kind==='external_receipt'?e.amount_minor:-e.amount_minor),e.recorded_method?depositMethods[e.recorded_method]:'No money movement',e.reference,e.reason,e.target_event_id??'',e.actor_id])}
function metadata(name:string,tenant:string,property:string,title:string,generatedAt:string,zoneName:string):ReportCell[][]{return [['iRatePilot PMS',title],['Property',name],['Tenant ID',tenant],['Property ID',property],['Currency','USD'],['Generated at',generatedAt],['Current property time zone',zoneName],['Basis','Manually recorded refundable security funds. No processor action, verified settlement, approved refund, revenue, or folio payment is implied.'],['Scope','Explicit security-deposit books only. Legacy folio payments are not reclassified.'],['History','Current reservation labels are descriptive. Event versions, references, recording zones and dates remain recorded history.'],[]]}
function totalRows(t:DepositTotals):ReportCell[][]{return [['Received USD',reportMoney(t.received_minor)],['Externally returned USD',reportMoney(t.refunded_minor)],['Receipt record reductions USD',reportMoney(t.reduced_minor)],['Recorded security funds remaining USD',reportMoney(t.held_minor)]]}
export function depositDetailCsv(data:DepositDetail,propertyName:string):ReportCell[][]{return [...metadata(propertyName,data.tenant_id,data.property_id,'Reservation security-deposit record',data.generated_at,data.property_time_zone),['Reservation',data.reservation.id],['Current guest name',data.reservation.guest_name],['Source reference',data.reservation.source_booking_id],['Current status',depositStatusLabel(data.reservation)],['Arrival',data.reservation.arrival],['Departure',data.reservation.departure],['Book',data.book?.id??'No deposit record'],['Book version',data.version],['Recording time zone',data.recording_time_zone],['Current recording date',data.recording_date],...(data.totals?totalRows(data.totals):[['Amount basis','No deposit record; no zero balance is inferred']] as ReportCell[][]),[],depositEventHeaders,...depositEventRows(data.events),[],['Original receipt balances'],['Receipt event','Received USD','Returned USD','Reduced USD','Remaining recorded USD'],...data.refundable_receipts.map(t=>[t.event_id,reportMoney(t.received_minor),reportMoney(t.refunded_minor),reportMoney(t.reduced_minor),reportMoney(t.remaining_minor)])]}
export function depositRegisterCsv(data:DepositRegister,propertyName:string):ReportCell[][]{return [...metadata(propertyName,data.tenant_id,data.property_id,'Current security-deposit register',data.generated_at,data.property_time_zone),['Books',data.summary.book_count],['Books with remaining funds',data.summary.with_held_count],['Recorded zero books',data.summary.zero_held_count],['Ended stays with remaining funds',data.summary.ended_with_held_count],['Ended stays remaining USD',reportMoney(data.summary.ended_held_minor)],['Review basis','Checked out or cancelled stays with positive remaining records. This is not an approved-refund list.'],...totalRows(data.totals),[],['Reservation','Source','Source reference','Current guest name','Current status','Arrival','Departure','Book','Version','Creation operating model','Frozen recording zone','Created at','Created by','Last recorded at','Received USD','Returned USD','Reduced USD','Remaining USD','Financial review required'],...data.rows.map(({reservation:r,book:b,financial_review_required:review})=>[r.id,r.source,r.source_booking_id,r.guest_name,depositStatusLabel(r),r.arrival,r.departure,b.id,b.version,b.creation_operating_model,b.recording_time_zone,b.created_at,b.created_by,b.updated_at,...['received_minor','refunded_minor','reduced_minor','held_minor'].map(k=>reportMoney(b.totals[k as keyof DepositTotals])),review?'Yes':'No'])]}
export function depositActivityCsv(data:DepositActivity,propertyName:string):ReportCell[][]{return [...metadata(propertyName,data.tenant_id,data.property_id,'Recorded security-deposit activity',data.generated_at,data.property_time_zone),['Recording civil date from',data.period.start],['Recording civil date until (exclusive)',data.period.end],['Period basis','Stored recording dates in each book’s frozen zone. There is no single UTC interval; period activity is not the current balance.'],['Event count',data.totals.event_count],['Received USD',reportMoney(data.totals.received_minor)],['Externally returned USD',reportMoney(data.totals.refunded_minor)],['Receipt record reductions USD',reportMoney(data.totals.reduced_minor)],['Net held-record effect USD',reportMoney(data.totals.held_effect_minor)],[],[...depositEventHeaders,'Current guest name','Current source reference','Current status'],...data.rows.map(row=>[...depositEventRows([row.event])[0],row.reservation.guest_name,row.reservation.source_booking_id,depositStatusLabel(row.reservation)])]}
